from pathlib import Path
import re
root=Path('/Users/neon/.codex/experiments/soodles46-verify-noodle-20260917/draft')
for p in root.rglob('*.md'):
 for target in re.findall(r'\\]\\((["'^)]+)'"\\)',p.read_text()):
  if '://' in target:continue
  rel=p.relative_to(root).parent/target
  if not ((root/rel).exists() or (Path.cwd()/rel).exists()):print(p.relative_to(root),repr(target),str(rel))
